def count_divisors(n):
    """Calculates the number of positive divisors of n."""
    if n == 1:
        return 1

    count = 1
    temp = n
    i = 2
    while i * i <= temp:
        exponent = 0
        while temp % i == 0:
            exponent += 1
            temp //= i
        if exponent > 0:
            count *= (exponent + 1)
        i += 1
    if temp > 1:
        count *= 2  # The remaining factor is prime
    return count

