import math

def d(n):
    """Calculates the number of divisors of n."""
    if n == 1:
        return 1
    count = 1
    n = abs(n)
    p = 2
    while p * p <= n:
        exponent = 0
        while n % p == 0:
            exponent += 1
            n //= p
        if exponent > 0:
            count *= (exponent + 1)
        p += 1
    if n > 1:
        count *= 2
    return count

def check_condition(k):
    """Checks if d(2k^3) == 2k."""
    if k <= 0:
        return False

    LHS = d(2 * (k**3))
    RHS = 2 * k
    return LHS == RHS

solutions = []
# Check up to k=30 based on initial manual checks and observations
for k in range(1, 31):
    if check_condition(k):
        solutions.append(k)

print(f"Solutions found for k <= 30: {solutions}")

def tau(N):
    factors = {}
    d = 2
    temp = N
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    count = 1
    for exponent in factors.values():
        count *= (exponent + 1)
    return count

def check_k(k):
    return tau(2 * (k**3)) == 2 * k

solutions = []
for k in range(1, 16):
    if check_k(k):
        solutions.append(k)
print(f"Solutions found up to k=15: {solutions}")

import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def num_divisors(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    divisors = 1
    for exponent in factors.values():
        divisors *= (exponent + 1)
    return divisors

